class CallCenter:
    def __init__(self):
      self.customers = []

    def is_empty(self):
      return self.customers == []

    def add(self, x):
      self.customers.insert(0, x)

    def next(self):
      return self.customers.pop()



c = CallCenter()

while True:
    n = input()
    if n == 'end':
        break
    c.add(n)

time = 0
while not c.is_empty():
    x = c.next()
    if x == "general":
      time = time + 5
    else:
      time = time + 10

print(time)
